// Loading title modules: the executable (default.xex) and the DLLs it loads
// with XexLoadImage. Registers their recompiled functions, resolves their
// imports, and runs DLL entry points.

#pragma once

#include <cstdint>
#include <string>
#include <string_view>
#include <vector>

struct PPCContext;
struct PPCFuncMapping;

namespace h3::kernel
{
    // A DLL that was recompiled alongside the executable. The table is
    // generated by H3RecompLib/CMakeLists.txt from H3RecompLib/modules/.
    struct RecompiledModule
    {
        const char* name;
        uint32_t imageBase;
        uint32_t imageSize;
        PPCFuncMapping* functions;
    };

    // Terminated by an entry with a null name.
    extern const RecompiledModule kRecompiledModules[];

    // A loaded title module: the executable or a DLL.
    struct Module
    {
        std::string name;  // file name, e.g. "WavesLibDLL.dll"
        uint32_t base = 0;
        uint32_t size = 0;
        uint32_t entryPoint = 0;
        uint32_t ldrEntry = 0;     // X_LDR_DATA_TABLE_ENTRY; also the module handle
        uint32_t exportTable = 0;  // XEX export table in guest memory, 0 if none
        uint32_t loadCount = 1;
        std::vector<uint8_t> headers;  // the XEX headers (host copy)
    };

    // Loads the title executable from a host path: copies the image into
    // guest memory, registers its recompiled functions and resolves its
    // imports. Also fills in g_module.
    bool LoadExecutable(const char* path);

    // The module record for default.xex (valid after LoadExecutable).
    const Module& ExecutableModule();

    // XexLoadImage. Loads a DLL by guest path (game:\foo.dll), or bumps the
    // load count if it's already loaded. Runs its entry point with
    // DLL_PROCESS_ATTACH on first load, using ctx's thread. Returns null if
    // the file is missing or wasn't recompiled.
    Module* LoadModule(std::string_view guestPath, PPCContext& ctx);

    // Looks a loaded module up by its handle (LDR entry address).
    Module* ModuleFromHandle(uint32_t handle);

    // Looks a loaded module up by file name, case-insensitively.
    Module* FindModule(std::string_view name);

    // Address of an export by ordinal, or 0.
    uint32_t GetProcAddress(const Module& module, uint32_t ordinal);
}
